package com.yeyamo_mobile.api.feed_service.infrastructure.security;import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.security.oauth2.jwt.Jwt;class SecurityConfigTests{@Test void mapsRoles(){Jwt jwt=new Jwt("t",Instant.now(),Instant.now().plusSeconds(60),Map.of("alg","HS256"),Map.of("sub","u1","roles",List.of("USER")));var a=new SecurityConfig.JwtRolesConverter().convert(jwt);assertEquals("u1",a.getName());assertTrue(a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_USER")));}}
